def largestAfterAdjacentSwaps(nums, k):
    a = list(nums)
    n = len(a)
    for i in range(n):
        if k == 0:
            break
        w = a[i:i + k + 1]
        mx = max(w)
        j = i + w.index(mx)
        if j > i:
            a.insert(i, a.pop(j))
            k -= j - i
    return a
